"""Assemble already measured focused independent review, no CAD mutations."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).parent
def load(name):return json.loads((OUT/name).read_text(encoding='utf-8'))
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
before=load('reviewer_routing_before.json');after=load('reviewer_routing.json');mechanics=load('reviewer_mechanics.json');models=load('reviewer_models.json');negative=load('reviewer_RF_negative.json');gnd=load('reviewer_ground.json');drc=load('reviewer_LOGIC_positive_drc.json')
native=ROOT/'design/MeshRepeater2_Logic/MeshRepeater2_Logic.kicad_pcb'
assert after['sha256']==negative['native_input_sha256']==gnd['input_sha256']==sha(native)
assert not any(drc[n] for n in ['ignored_checks','violations','unconnected_items','schematic_parity'])
assert after['protected']==before['protected']
assert after['protected']['J10']['pose']==[35.7,31.3,0.0]
def tracks_for(label):return {x['uuid']:x for x in after['selected_paths'][label]['tracks']}
shared=set(tracks_for('MCU_power'))&set(tracks_for('MODEM_power_branch'))
assert not shared
for name in ['MCU_power','MODEM_power_branch','BAT_sense']:
 assert after['selected_paths'][name]['tracks']==before['selected_paths'][name]['tracks']
for name in ['ANT_RF','ANT_SMA']:
 assert {x['uuid']:x for x in after['nets'][name]['segments']}=={x['uuid']:x for x in before['nets'][name]['segments']}
assert after['nets']['ANT_RF']['opposite_GND_uncovered_estimate_mm']==0 and negative['status']=='PASS' and gnd['component_count']==1
route=[]
for net,label in [('MOSI_RF','MOSI'),('MISO_MCU','MISO'),('RADIO_RST','RESET')]:
 a=after['nets'][net];b=before['nets'][net];returns=after['selected_paths'][label]['via_return_distances']
 route.append({'net':net,'exact_all_net_segment_sum_before_mm':b['segment_sum_mm'],'exact_all_net_segment_sum_after_mm':a['segment_sum_mm'],'all_net_vias_before':b['via_count'],'all_net_vias_after':a['via_count'],'longest_opposite_ground_gap_before_mm':b['longest_missing_span_mm'],'longest_opposite_ground_gap_after_mm':a['longest_missing_span_mm'],'opposite_GND_uncovered_estimate_after_mm':a['opposite_GND_uncovered_estimate_mm'],'closest_lateral_GND_on_uncovered_samples_mm':a['lateral_ground_on_uncovered_samples_mm'],'selected_path_return_barrels':returns,'max_selected_path_return_barrel_mm':max(v['nearest_GND_barrel_mm'] for v in returns),'selected_whole_segment_path_sum_after_mm':after['selected_paths'][label]['whole_selected_segments_sum_mm']})
findings=[{'id':'R1','status':'FIXED_FOCUSED_SCOPE','reason':'The independently confirmed long MOSI/MISO/RESET detours and remote SPI layer returns are removed. Short remaining opposite-layer voids are bounded and have nearby connected same-layer GND; this is not a continuous opposite plane or measured signal-integrity guarantee.','metrics':route}, {'id':'R2','status':'FIXED','ANT_RF_old_axis_gap_mm':before['nets']['ANT_RF']['longest_missing_span_mm'],'ANT_RF_new_axis_gap_mm':0,'negative_rule_regression':'PASS: items_not_allowed error names RF opposite layer permits GND and RF only and targets controlled old RXEN segment UUID.','inherited_SMA_launch_gap_mm':after['nets']['ANT_SMA']['longest_missing_span_mm'],'RF_track_geometry_unchanged':True},*mechanics['findings'],{'id':'M-02','status':models['M-02'],'bracket_width_mm':models['switch_models'][0]['bracket_width_mm'],'four_switch_footprints_byte_unchanged':True}]
order=['R1','R2','M-01','M-02','DOC-01'];findings.sort(key=lambda f:order.index(f['id']))
report={'reviewer':'Independent reviewer of corrections; did not author or modify native CAD. Controlled negative probe written only to disposable reviewer subdirectory.','date':'2026-10-12','scope':'Five new findings from audit/independent_2026_10_12. Read-only focused acceptance, not a fresh complete electronics qualification.','status':'PASS_FIVE_CORRECTIONS_WITH_INHERITED_OPEN_RISKS','native_LOGIC_sha256':after['sha256'],'findings':findings,'additional_confirmed_P2_in_corrected_areas':[],'positive_native_LOGIC_DRC':{'violations':0,'unconnected':0,'schematic_parity':0,'ignored_checks':0,'included_severities':drc['included_severities'],'native_unchanged_by_all_review_steps':True},'preservation':{'J10_ISP_pose':[35.7,31.3,0],'M1_M2_J11_J201_R27_all_pad_netnames_and_poses_unchanged':True,'USB_edge_module_pose_unchanged':True,'SYS_MCU_modem_branches_shared_track_uuids':sorted(shared),'SYS_branches_and_BAT_sense_routes_byte_geometry_unchanged':True,'RF_trace_geometry_unchanged':True,'GND_physical_components':1,'old_independent_audit_not_written':True},'pending_physical_tests':['Real mating stops, depth, cable retention, crimp and pin polarity for newly selected J3/J5 cable parts.','EMI/RF measurements, SPI operation at actual firmware settings and transient modem/MCU supply measurements.','Manufacturing stack, real module geometry and assembled mechanical access; STEP envelopes alone are not hardware qualification.'],'inherited_open_design_risks':[{'id':'E-I1','status':'UNCHANGED','description':'Existing LMV431 balancers with 2 ohm resistors are not guaranteed to stay within cathode current limits. The correction task did not change their circuit; proposed remedies require a distinct design decision under prior user conditions.','source':'https://www.ti.com/lit/ds/symlink/lmv431.pdf'}, {'id':'E-I2','status':'UNCHANGED','description':'Existing CN3722 LTO divider does not guarantee TPS63802 VIN<=5.5V in battery-absent charger OVP operation. Divider-only normal-CV tolerance proof does not cover that mode. Separate remedy was not applied in this focused correction review.','source':['https://consonance-elec.com/static/upload/file/20231218/1702867485736775.pdf','https://www.ti.com/lit/ds/symlink/tps63802.pdf']}],'exports_and_assembly_release':'Root regenerates/checks derived exports after native freeze; their yet-in-progress status is not represented as passed by this report.','evidence_sha256':{name:sha(OUT/name) for name in ['reviewer_mechanics.json','reviewer_models.json','reviewer_routing_before.json','reviewer_routing.json','reviewer_ground.json','reviewer_LOGIC_positive_drc.json','reviewer_RF_negative.json','reviewer_RF_negative_drc.json']}}
(OUT/'reviewer.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# Независимая проверка исправлений Mesh Repeater 2.0','',f"Дата: 12.10.2026. Проверенный LOGIC SHA256: `{after['sha256']}`.",'','Пять новых замечаний аудита устранены в пределах проверенного объёма. Дополнительных подтверждённых P2 в исправленных областях не найдено. Схема LTO имеет два прежних открытых риска, перечисленных ниже; их устранение этим результатом не подтверждается. Проверка не изменяла native CAD.','', '## R1 — трассы SPI и RESET','', '| Цепь | Сумма всех сегментов, было → стало | Via, было → стало | Максимальный пробел GND на противоположном слое, было → стало | Максимальное расстояние к ближайшему GND-barrel у переходов выбранного пути |','|---|---|---|---|---|']
for r in route:
 lines.append(f"| {r['net']} | {r['exact_all_net_segment_sum_before_mm']:.3f} → {r['exact_all_net_segment_sum_after_mm']:.3f} мм | {r['all_net_vias_before']} → {r['all_net_vias_after']} | {r['longest_opposite_ground_gap_before_mm']:.3f} → {r['longest_opposite_ground_gap_after_mm']:.3f} мм | {r['max_selected_path_return_barrel_mm']:.3f} мм |")
lines+=['','Суммы учитывают реальные длины всех сегментов каждой цепи. Отдельный графовый путь суммирует целые сегменты и не является точной длиной, обрезанной по краям контактных площадок. Проверка GND использует фактическую заливку, дорожки, площадки и переходы с шагом 0,025 мм.','', 'Сплошной противоположный полигон под каждой точкой не заявляется. На участках без него ближайшая боковая GND-медь того же слоя имеет медианное расстояние 0,301 мм для MOSI/MISO и 0,320 мм для RESET; максимумы — 1,001 / 1,085 / 1,958 мм. Все GND-острова связаны в один физический компонент через реальные металлизированные переходы. Критические MISO-переходы теперь имеют возвратные GND-barrels на 0,849 и 0,851 мм вместо 6,140 и 4,528 мм. Этого достаточно, чтобы закрыть подтверждённые обходы и удалённые возвраты; EMI и работу SPI подтверждают измерением образца.','', '## R2 — RF-возврат и контрольная проба','', 'RXEN выведен из области B.Cu под антенной. Обнаруженный ранее пробел 0,900 мм под ANT_RF отсутствует при свежем осевом контроле. Геометрия RF-дорожек сохранена. Новое правило RF_GROUND_GUARD запрещает в этой области цифровые track/via и допускает GND-заливку.','', 'В отдельную временную копию возвращена прежняя B.Cu RXEN-дорожка (37,4; 8,6) → (49,2; 8,6), ширина 0,25 мм. DRC выдал `items_not_allowed` именно от правила `RF opposite layer permits GND and RF only` и на UUID добавленного сегмента. Положительный DRC native LOGIC: 0 нарушений, 0 неподключений, 0 расхождений со схемой, 0 отключённых проверок; проверены все severity и all-track-errors. Исходный пробел 1,250 мм у собственного SMA launch сохранён и не выдаётся за восстановленный непрерывный RF-полигон. Контрольная копия не является производственным файлом.','', '## M-01 / M-02 / DOC-01','', '- J3/J5: в ведомость добавлены два корпуса Connfly I-DS1071-SCB01x4 и восемь контактов T-DS1071-SC600 из ДАН; для пяти сборок — 10 и 40. Первичный чертёж DS1071 подтверждает совместимую серию DS1022, штырь 0,64 мм и шаг 2,54 мм. Таблица кабелей совпадает с native распиновкой. Реальная глубина посадки и обжим требуют проверки на деталях.','- Свежий FreeCAD-контроль обоих SW STEP подтверждает ширину скобы 8,41 мм. Все четыре используемые базовые/вариантные SW footprints байтово совпадают с опубликованным исходником: посадка и модельные трансформы сохранены.','- H1–H4: PTH/GND подтверждены чтением native. Три BOM-значения, скрытые native/схемные/library поля и authoritative модельные варианты синхронизированы как M3 GND contact; генератор сохраняет эти значения. Схема Interconnect и четыре hole footprints изменены только заменой ошибочных строк M3 NPTH.','', '## Сохранение конструкции','', 'ISP J10 оставлен (35,7; 31,3), 0°. Положение M1/M2, боковой доступ к USB, фактические имена цепей всех контактных площадок M1/M2/J11/J201/R27 сохранены. Положительные ветви SYS_3V3 к MCU и FB1 модема не имеют общих сегментов; обе ветви и BAT_sense имеют прежнюю геометрию. Старый независимый аудит не перезаписывался. Производные экспорты и сборочные документы root проверяет отдельно после фиксации CAD.','', '## Прежние риски LTO и проверки образца','', '- E-I1: балансир с LMV431 и 2 Ом не гарантирует ограничение катодного тока; его схема в этих исправлениях не менялась.','- E-I2: LTO-делитель CN3722 не гарантирует вход TPS63802 ≤5,5 В при отсутствии батареи в режиме OVP зарядника. Расчёт обычного CV по допускам этот режим не покрывает.','', 'Остаются измерения EMI/RF, обмен SPI на фактической частоте прошивки, импульсная нагрузка модема и её влияние на MCU, реальная сборка модулей/кабелей и механический доступ. Это не заменяется DRC или упрощёнными STEP-моделями.','', 'Полные числа, SHA и ссылки на доказательства: [reviewer.json](reviewer.json), [маршруты](reviewer_routing.json), [земля](reviewer_ground.json), [положительный DRC](reviewer_LOGIC_positive_drc.json), [отрицательная проба](reviewer_RF_negative.json), [BOM/native](reviewer_mechanics.json), [STEP/посадки](reviewer_models.json).','']
(OUT/'reviewer.md').write_text('\n'.join(lines),encoding='utf-8')
print(json.dumps({'status':report['status'],'findings':[f['id'] for f in findings],'positive_DRC':report['positive_native_LOGIC_DRC'],'shared_SYS_tracks':shared if isinstance(shared,list) else sorted(shared)},ensure_ascii=False))
